SELECT data['commit']['collection']::STRING AS event, COUNT(*) AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT data['commit']['collection']::STRING AS event, COUNT(*) AS count, COUNT(DISTINCT data['did']::STRING) AS users FROM bluesky WHERE data['kind']::STRING = 'commit' AND data['commit']['operation']::STRING = 'create' GROUP BY event ORDER BY count DESC;
SELECT data['commit']['collection']::STRING AS event, EXTRACT(HOUR FROM TO_TIMESTAMP(data['time_us']::INT64, 6)) AS hour_of_day, COUNT(*) AS count FROM bluesky WHERE data['kind']::STRING = 'commit' AND data['commit']['operation']::STRING = 'create' AND data['commit']['collection']::STRING IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT data['did']::STRING AS user_id, MIN(TO_TIMESTAMP(data['time_us']::INT64, 6)) AS first_post_ts FROM bluesky WHERE data['kind']::STRING = 'commit' AND data['commit']['operation']::STRING = 'create' AND data['commit']['collection']::STRING = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT data['did']::STRING AS user_id, (MAX(data['time_us']::INT64) - MIN(data['time_us']::INT64)) / 1000 AS activity_span FROM bluesky WHERE data['kind']::STRING = 'commit' AND data['commit']['operation']::STRING = 'create' AND data['commit']['collection']::STRING = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
